<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $group = $args['group']; $status = sd_group_status( $group->id ); ?><header class="sd-group-header"><?php if ( function_exists( 'bp_group_cover_url' ) && bp_group_cover_url( $group ) ) : ?><div class="sd-group-cover"><img src="<?php echo esc_url( bp_group_cover_url( $group ) ); ?>" alt=""></div><?php endif; ?><div class="sd-group-header-content"><div class="sd-group-avatar"><?php echo wp_kses_post( bp_get_group_avatar( $group, array( 'type' => 'full', 'width' => 112, 'height' => 112 ) ) ); ?></div><div><span class="sd-badge"><?php echo esc_html( ucfirst( $group->status ) ); ?></span><h1><?php echo esc_html( bp_get_group_name( $group ) ); ?></h1><p><?php echo esc_html( wp_trim_words( bp_get_group_description( $group ), 30 ) ); ?></p><span class="sd-muted"><?php echo esc_html( absint( $group->total_member_count ) ); ?> <?php esc_html_e( 'members', 'social-discovery' ); ?></span></div><div class="sd-group-header-actions"><?php if ( is_user_logged_in() && function_exists( 'sd_core_api_group_membership' ) && 'banned' !== $status ) : ?><button class="sd-button" type="button" data-sd-group-action="<?php echo esc_attr( 'member' === $status || 'admin' === $status || 'mod' === $status ? 'leave' : ( 'private' === $group->status ? 'request' : 'join' ) ); ?>" data-sd-group-id="<?php echo esc_attr( $group->id ); ?>"><?php echo esc_html( sd_group_action_label( $group->id ) ); ?></button><?php endif; ?></div></div></header>
